#include "sim/typed/ai_firing.h"
#include "core/pymath.h"
#include <algorithm>
#include <cmath>
namespace pvz::typed72 {
namespace {double mod(double x,double width){double r=std::fmod(x,width);if(r<0)r+=width;return r;}}
std::string_view ai_firing_reason_name(AiFiringReason r){switch(r){case AiFiringReason::own_mechanics:return "own_mechanics";case AiFiringReason::unknown_terrain:return "unknown_terrain";case AiFiringReason::target:return "target";case AiFiringReason::unreachable_targets:return "unreachable_targets";case AiFiringReason::open_corridor:return "open_corridor";default:return "blocked_corridor";}}
bool AiFiring::ballistic(const AiFiringCard& c){return !c.producer&&(c.behavior=="shoot"||c.lob)&&!(c.star||c.homing||c.name=="香蒲"||c.name=="猫尾草");}
std::optional<AiArcSolution> AiFiring::arc_solution(double dx,double dy,double speed,double gravity,bool high){const double b=gravity*dy-speed*speed,disc=b*b-gravity*gravity*(dx*dx+dy*dy);if(disc<0)return {};const double root=std::sqrt(disc),den=.5*gravity*gravity;const double first=(-b-root)/den,second=(-b+root)/den;double chosen=0.;if(first>1e-8)chosen=first;if(second>1e-8&&(!(chosen>0)||(high?second>chosen:second<chosen)))chosen=second;if(!(chosen>0))return {};const double t=std::sqrt(chosen);return AiArcSolution{t,dx/t,(dy-.5*gravity*t*t)/t};}
std::optional<double> AiFiring::body_entry(Point from,Point to,double tx,double foot,double height,double half_width){double low=0.,high=1.;const std::array<std::array<double,4>,2> axes={{{from.x,to.x,tx-half_width,tx+half_width},{from.y,to.y,foot-height,foot}}};for(const auto& a:axes){const double delta=a[1]-a[0];if(std::abs(delta)<1e-9){if(!(a[2]<=a[0]&&a[0]<=a[3]))return {};}else{double x=(a[2]-a[0])/delta,y=(a[3]-a[0])/delta;if(x>y)std::swap(x,y);low=std::max(low,x);high=std::min(high,y);if(low>high)return {};}}return low;}
bool AiFiring::clear_segment(Point from,Point to)const{const double dx=ai_wrap_delta(from.x,to.x,frame_.width),dy=to.y-from.y;const int64_t steps=std::max<int64_t>(1,int64_t(std::hypot(dx,dy)/(frame_.tile*.2))+1);const auto& tiles=frame_.terrain.solid;if(tiles.empty()||tiles.front().empty())return true;const int64_t rows=tiles.size(),cols=tiles.front().size();for(int64_t i=0;i<=steps;++i){const int64_t row=int64_t(std::floor((from.y+dy*i/steps)/frame_.tile));const int64_t col=int64_t(std::floor(mod(from.x+dx*i/steps,frame_.width)/frame_.tile))%cols;if(row>=rows||(row>=0&&tiles[size_t(row)][size_t(col)]))return false;}return true;}
bool AiFiring::clear_guided_arc(Point p,double target_x,double foot,double height,double speed,double gravity)const{if(!clear_segment(p,{p.x,p.y-.05*frame_.tile}))return false;const double ty=foot-.35*height,target=p.x+ai_wrap_delta(p.x,target_x,frame_.width);auto solution=arc_solution(target-p.x,ty-p.y,speed,gravity);if(!solution)return false;double vx=solution->vx,vy=solution->vy;const int limit=std::min(600,std::max(40,int(solution->time*1.8)));for(int tick=0;tick<limit;tick+=4){if(tick&&tick%20==0){const double keep=std::max(speed,std::hypot(vx,vy));if(auto aimed=arc_solution(target-p.x,ty-p.y,keep,gravity)){const double ax=vx*.74+aimed->vx*.26,ay=vy*.74+aimed->vy*.26,norm=std::hypot(ax,ay);if(norm>1e-9){vx=ax/norm*keep;vy=ay/norm*keep;}}}const Point next{p.x+4*std::copysign(std::max(0.,std::abs(vx)-gravity),vx),p.y+4*vy+gravity*20};vy+=gravity*8;if(auto entry=body_entry(p,next,target,foot,height,frame_.tile*.35))return clear_segment(p,{p.x+(next.x-p.x)* *entry,p.y+(next.y-p.y)* *entry});if(!clear_segment(p,next))return false;p=next;}return false;}
bool AiFiring::clear_arc(Point p,Point target,const AiFiringCard& card,std::optional<double> foot,std::optional<double> height)const{const double dx=ai_wrap_delta(p.x,target.x,frame_.width),dy=target.y-p.y;const bool mortar=card.behavior=="mortar",high=mortar||card.name=="甜椒投手";const double speed=frame_.tile*(mortar?.08:high?7./80.:7./120.),gravity=frame_.tile/(high?2500.:5000.);if(!high&&foot)return clear_guided_arc(p,target.x,*foot,height&&*height?*height:1.5*frame_.tile,speed,gravity);const auto solution=arc_solution(dx,dy,speed,gravity,high);if(!solution)return false;const double t=solution->time,vx=solution->vx,vy=solution->vy;const int64_t steps=std::max<int64_t>(2,int64_t(t*(std::abs(vx)+std::abs(vy)+gravity*t)/(frame_.tile*.2))+1);Point previous=p;for(int64_t i=1;i<=steps;++i){const double clock=t*i/steps;Point next{p.x+vx*clock,p.y+vy*clock+.5*gravity*clock*clock};if(!clear_segment(previous,next))return false;previous=next;}return true;}
AiFiringAssessment AiFiring::assessment(const AiFiringCard& card,Point p,int facing){if(!ballistic(card))return {true,AiFiringReason::own_mechanics,{}};if(frame_.terrain.solid.empty())return {true,AiFiringReason::unknown_terrain,{}};const int64_t row=int64_t(std::floor(p.y/frame_.tile)),col=int64_t(std::floor(mod(p.x,frame_.width)/frame_.tile));const auto key=std::tuple{card.id,row,col,facing>=0?1:-1};if(auto it=memo_.find(key);it!=memo_.end())return it->second;return memo_.emplace(key,check(card,col,row,facing)).first->second;}
std::optional<int> AiFiring::direction(const AiFiringCard& card,Point p,int facing){facing=facing>=0?1:-1;const auto chosen=assessment(card,p,facing);if(chosen.allowed&&chosen.reason!=AiFiringReason::open_corridor)return facing;const auto other=assessment(card,p,-facing);if(other.allowed&&other.reason==AiFiringReason::target&&other.distance.value_or(0.)<=4*frame_.tile)return -facing;return chosen.allowed?std::optional<int>(facing):std::nullopt;}
const AiFiringSignature& AiFiring::signature(){if(signature_)return *signature_;AiFiringSignature value{frame_.width,frame_.tile,frame_.terrain.solid,{}};for(auto& row:value.solid)for(auto& cell:row)cell=bool(cell);for(const auto& t:frame_.targets)value.targets.push_back({py::roundn(t.position.x,2),py::roundn(t.position.y,2),py::roundn(t.height?t.height:1.5*frame_.tile,2)});std::sort(value.targets.begin(),value.targets.end());signature_=std::make_shared<AiFiringSignature>(std::move(value));return *signature_;}
AiFiringAssessment AiFiring::check(const AiFiringCard& card,int64_t col,int64_t row,int facing)const{facing=facing>=0?1:-1;const double tile=frame_.tile;double x=(col+.5)*tile,y=(row+.5)*tile;if(card.lob){y=row*tile;if(card.behavior=="mortar"){x+=facing*.28*tile;y+=.25*tile;}}else x+=facing*.3*tile;const std::array<int,2> directions={facing,-facing};const size_t direction_count=card.name=="裂荚射手"?2:1;const std::array<double,3> offsets=card.name=="三向射手"?std::array<double,3>{-tile,0.,tile}:std::array<double,3>{0.,0.,0.};const size_t offset_count=card.name=="三向射手"?3:1;double reach=std::min(32*tile,card.range&&*card.range?*card.range:12*tile);if(reach<32)reach*=tile;std::vector<const AiFiringTarget*> targets;for(const auto& target:frame_.targets){const double dx=ai_wrap_delta(x,target.position.x,frame_.width);bool ahead=false;for(size_t d=0;d<direction_count;++d)ahead|=dx*directions[d]>0.;if(ahead&&std::abs(dx)<=reach&&std::abs(target.position.y-y)<6*tile)targets.push_back(&target);}std::stable_sort(targets.begin(),targets.end(),[&](auto a,auto b){return std::abs(ai_wrap_delta(x,a->position.x,frame_.width))<std::abs(ai_wrap_delta(x,b->position.x,frame_.width));});for(const auto* t:targets){const double dx=ai_wrap_delta(x,t->position.x,frame_.width),height=t->height?t->height:1.5*tile;if(card.lob){const double ty=t->position.y-tile*(card.behavior=="mortar"?1.:.7);if(clear_arc({x,y},{x+dx,ty},card,t->position.y,height))return {true,AiFiringReason::target,std::abs(dx)};}else for(size_t i=0;i<offset_count;++i){const double sy=y+offsets[i];if(t->position.y-height<=sy&&sy<=t->position.y&&clear_segment({x,sy},{x+dx,sy}))return {true,AiFiringReason::target,std::abs(dx)};}}if(!targets.empty())return {false,AiFiringReason::unreachable_targets,{}};bool allowed=false;for(size_t d=0;d<direction_count&&!allowed;++d){if(card.lob)allowed=clear_arc({x,y},{x+directions[d]*std::min(reach,4*tile),y+.3*tile},card,y+tile,1.5*tile);else for(size_t i=0;i<offset_count&&!allowed;++i)allowed=clear_segment({x,y+offsets[i]},{x+directions[d]*std::min(reach,3*tile),y+offsets[i]});}return {allowed,allowed?AiFiringReason::open_corridor:AiFiringReason::blocked_corridor,{}};}
std::optional<int> AiFiringFailures::direction(AiFiring& firing,const AiFiringCard& card,Point p,int facing,double now,double width,double tile){if(!AiFiring::ballistic(card))return facing;const Key key={card.id,int64_t(std::floor(mod(p.x,width)/(tile*.5))),int64_t(std::floor(p.y/(tile*.5))),facing>=0?1:-1};const auto& signature=firing.signature();auto previous=entries.find(key);std::optional<int> result;if(previous==entries.end()||*previous->second.signature!=signature||previous->second.until<=now){result=firing.direction(card,p,facing);if(!result){const uint64_t repeats=previous!=entries.end()&&*previous->second.signature==signature?previous->second.repeats+1:1;const uint64_t order=previous!=entries.end()?previous->second.order:serial++;entries.insert_or_assign(key,Failure{firing.shared_signature(),now+std::min(2.,.5*repeats),repeats,order});++blocked_lane_count;if(entries.size()>128){std::vector<std::pair<Key,const Failure*>> sorted;for(const auto& [k,v]:entries)sorted.emplace_back(k,&v);std::sort(sorted.begin(),sorted.end(),[](const auto& a,const auto& b){return std::tie(a.second->until,a.second->order)<std::tie(b.second->until,b.second->order);});for(size_t i=0;i<32;++i)entries.erase(sorted[i].first);}}else entries.erase(key);}if(!result){lane_blocked=true;last_blocked_card=card.id;}else if(*result!=facing)++turn_count;return result;}
} // namespace pvz::typed72
